// ── Append into the Example Answers data ────────────────────────────────
EX2026.forEach(function(e){ e.is2026 = true; e.idx = examples[e.sec].items.push(e) - 1; });
const EX2026_BY_KEY = {};
EX2026.forEach(function(e){ EX2026_BY_KEY[e.key] = e; });

// 2026 question ids also get the existing (older-year) example for their question type
Object.assign(exampleLookup, {
  'c1_2026_1a':{sec:0,item:0}, 'c1_2026_1b':{sec:0,item:1}, 'c1_2026_2a':{sec:0,item:2}, 'c1_2026_2b':{sec:0,item:3},
  'c1_2026_3c':{sec:1,item:0}, 'c1_2026_3d':{sec:1,item:0}, 'c1_2026_4d':{sec:1,item:1},
  'c2_2026_1a':{sec:2,item:0}, 'c2_2026_1b':{sec:2,item:1}, 'c2_2026_2':{sec:2,item:2},
  'c2_2026_3':{sec:3,item:0}, 'c2_2026_4':{sec:3,item:1}
});

// Which 2026 script set matches a question id (any year) by question type
function get2026ForQuestion(qid) {
  const m = /(?:^|_)c([12])_(?:\d{4}_)?([0-9][a-d]?)$/.exec(qid);
  if (!m) return null;
  let part = m[2];
  if (m[1] === '2' && /^4[a-d]$/.test(part)) part = '4';   // older music Q4 sub-parts
  if (m[1] === '2' && /^[23][a-d]$/.test(part)) part = part[0];
  return EX2026_BY_KEY['c' + m[1] + '_' + part] || null;
}

// ── Override: getExampleForQuestion now true if either source exists ────
const _baseGetExample = getExampleForQuestion;
getExampleForQuestion = function(qid){ return _baseGetExample(qid) || get2026ForQuestion(qid); };

function build2026ScriptCard(ex, s, compact) {
  const workedHTML = s.worked ? s.worked.map(w => `<div class="ex-point">${w}</div>`).join('') : '';
  const improveHTML = s.improve ? `<div class="ex-what-improve"><div class="ex-improve-head">📈 To reach full marks</div>${s.improve.map(i=>`<div class="ex-point ex-point-red">${i}</div>`).join('')}</div>` : '';
  const full = s.mark.split('/')[0] === s.mark.split('/')[1];
  return `<div class="ex-card" style="margin-bottom:0.8rem">
    <div class="ex-card-header">
      <div class="ex-stripe" style="background:${full ? 'var(--success)' : 'var(--gold)'}"></div>
      <div class="ex-meta">
        <div class="ex-badges">
          <span class="ex-badge ex-badge-2026">Summer 2026 script</span>
          <span class="ex-badge ex-badge-mark">${s.mark}</span>
          <span class="ex-badge ex-badge-year">${ex.year} · ${ex.paper}</span>
        </div>
        <div class="ex-title">${compact ? '' : ex.qref + ' — '}${s.student}</div>
      </div>
    </div>
    <div class="ex-body">
      ${compact ? '' : `<div class="ex-question">${ex.question}</div>`}
      <div class="ex-response">${s.response.replace(/\n\n/g, '<br><br>')}</div>
      <div class="ex-examiner">${s.examiner}</div>
      ${workedHTML ? `<div class="ex-what-worked"><div class="ex-what-worked-head">✓ What worked well</div>${workedHTML}</div>` : ''}
      ${improveHTML}
    </div>
  </div>`;
}

// ── Override: Example Answers tab card ─────────────────────────────────
const _baseBuildExCard = buildExCard;
buildExCard = function(ex) {
  if (!ex.scripts) return _baseBuildExCard(ex);
  return `<div style="margin-bottom:2rem">
    <p style="font-family:'IBM Plex Mono',monospace;font-size:0.65rem;text-transform:uppercase;letter-spacing:2px;color:var(--muted);margin-bottom:0.6rem;">${ex.qref} · Summer 2026 · real marked scripts</p>
    ${ex.scripts.map(s => build2026ScriptCard(ex, s, false)).join('')}
  </div>`;
};

// ── Override: show newest (2026) examples first in the Example Answers tab
const _baseFilterExamples = filterExamples;
filterExamples = function() {
  const saved = examples.map(s => s.items);
  examples.forEach(function(sec){
    sec.items = sec.items.slice().sort((a,b) => (b.is2026?1:0) - (a.is2026?1:0));
  });
  try { _baseFilterExamples(); } finally { examples.forEach((s,i) => { s.items = saved[i]; }); }
};

// ── Override: Questions tab inline panel (2026 scripts + existing example)
const _baseBuildInline = buildInlineExample;
buildInlineExample = function(qid) {
  const ex26 = get2026ForQuestion(qid);
  const baseHTML = _baseGetExample(qid) ? _baseBuildInline(qid) : '';
  if (!ex26) return baseHTML;
  const isThisQ = /_2026_/.test(qid);
  const head = `<div class="ex-inline-disclaimer" style="background:#fff8e6;border-bottom-color:#f0dca8"><strong>🆕 Summer 2026 scripts</strong> — ${isThisQ ? 'real anonymised answers to <em>this exact question</em>' : 'real anonymised answers to the 2026 version of this question type (' + ex26.qref + '). Texts and wording change every year — look at the structure'}.</div>`;
  const cards = ex26.scripts.map(s => build2026ScriptCard(ex26, s, true)).join('');
  const inner = head + `<div style="padding:0.8rem 0.8rem 0">${cards}</div>`;
  if (baseHTML) {
    // insert 2026 content at the top of the existing panel
    return baseHTML.replace(/(<div class="ex-inline-panel" id="ex-inline-[^"]*">)/, '$1' + inner + '<div style="font-family:\'IBM Plex Mono\',monospace;font-size:0.62rem;text-transform:uppercase;letter-spacing:2px;color:var(--muted);padding:0.6rem 0.8rem 0;">Earlier-year examples</div>');
  }
  return `<div class="ex-inline-panel" id="ex-inline-${qid}">${inner}</div>`;
};

// Re-render now that the data and renderers are extended
if (typeof renderAll === 'function') { renderAll(); if (typeof applyFilters === 'function') applyFilters(); }
if (typeof buildExamplesTab === 'function') buildExamplesTab();
